test("Ellipse の配置・回転・最小/最大の大きさ・影・不透明度・表示・ロックは Box と同じ定義を持つ", () => {
  const names = [
    "placement",
    "x",
    "y",
    "constraintX",
    "constraintY",
    "rotation",
    "minWidth",
    "maxWidth",
    "minHeight",
    "maxHeight",
    "shadow",
    "opacity",
    "visibility",
    "locking",
  ];

  expect(
    names.map((name) => PrimitiveSchema.propDefinition("Ellipse", name)),
  ).toEqual(names.map((name) => PrimitiveSchema.propDefinition("Box", name)));
});

test("幅を fill にした Ellipse の最小幅が最大幅より大きいと、maxWidth を指すエラーが 1 件出る", () => {
  const document = documentWithEllipse({
    widthMode: "fill",
    minWidth: 500,
    maxWidth: 100,
  });

  expect(DesignDocument.collectErrors(document)).toEqual([
    expect.objectContaining({
      kind: "inverted-size-limits",
      nodeName: "target",
      prop: "maxWidth",
    }),
  ]);
});

test("モードを書いていない Ellipse は既定が fixed なので、最小/最大を逆に書いてもエラーにならない", () => {
  const document = documentWithEllipse({ minWidth: 500, maxWidth: 100 });

  expect(DesignDocument.collectErrors(document)).toEqual([]);
});

test("子を横に並べる親の中で幅を fill にした Ellipse に最小・最大の幅を書くと min-width / max-width が出る", () => {
  const style = setupEllipseStyle(
    { widthMode: "fill", minWidth: 40, maxWidth: 200 },
    Option.some("row"),
  );

  expect([style["min-width"], style["max-width"]]).toEqual(["40px", "200px"]);
});

test("モードを書いていない Ellipse は既定が fixed なので、書いた最小の幅は出ない", () => {
  expect("min-width" in setupEllipseStyle({ minWidth: 40 })).toBe(false);
});

test("高さを fill にした Ellipse に最小の高さを書くと min-height が出る", () => {
  expect(
    setupEllipseStyle(
      { heightMode: "fill", minHeight: 40 },
      Option.some("row"),
    )["min-height"],
  ).toBe("40px");
});

test("幅を fill にした Ellipse では幅の最小 / 最大のコントロールが出る", () => {
  const names = propNamesOf(ellipseSelection({ widthMode: "fill" }));

  expect(names).toContain("minWidth");
  expect(names).toContain("maxWidth");
});

test("高さを fill にした Ellipse では高さの最小 / 最大のコントロールが出る", () => {
  const names = propNamesOf(ellipseSelection({ heightMode: "fill" }));

  expect(names).toContain("minHeight");
  expect(names).toContain("maxHeight");
});

test("モードを書いていない Ellipse は既定が fixed なので、最小 / 最大のコントロールは出ない", () => {
  const names = propNamesOf(ellipseSelection({}));

  expect(names).not.toContain("minWidth");
  expect(names).not.toContain("maxWidth");
  expect(names).not.toContain("minHeight");
  expect(names).not.toContain("maxHeight");
});

